+        let d = dev(pts[prev[i]], pts[i], pts[next[i]]);
+        if d <= COLLINEAR {
+            heap.push(Reverse((d.to_bits(), i, 0)));
+        }
+    }
+    let mut left = n;
+    while let Some(Reverse((_, i, v))) = heap.pop() {
+        if !alive[i] || ver[i] != v {
+            continue;
+        }
+        if left <= 3 {
+            break;
+        }
+        alive[i] = false;
+        left -= 1;
+        let (a, b) = (prev[i], next[i]);
+        next[a] = b;
+        prev[b] = a;
+        for j in [a, b] {
+            ver[j] = ver[j].wrapping_add(1);
+            let d = dev(pts[prev[j]], pts[j], pts[next[j]]);
+            if d <= COLLINEAR {
