+    if !(d.is_finite() && d.abs() > 1e-18) {
+        return None;
+    }
+    let (uu, vv) = (dot(u, u), dot(v, v));
+    let c = Point2::new(a.x + (v.y * uu - u.y * vv) / d, a.y + (u.x * vv - v.x * uu) / d);
+    (c.x.is_finite() && c.y.is_finite()).then_some((c, d > 0.0))
