+    for i in 0..chords {
+        let (p, q) = (pts[i], pts[(i + 1) % n]);
+        let (u, w) = (sub(p, c), sub(q, c));
+        let t = cross(u, w).atan2(dot(u, w));
+        let t = if ccw { t } else { -t };
+        if !(t > 0.0 && t < PI) {
+            return None;
+        }
+        let half = 0.5 * dist(p, q);
+        if (2.0 * half).is_nan() || 2.0 * half < MIN_CHORD {
+            return None;
+        }
+        let s = r - (r * r - half * half).max(0.0).sqrt();
