+/// The arc of the open run `pts`, or `None` (module head).
+fn fit(pts: &[Point2], bound: f64) -> Option<Fit> {
+    let (a, b) = (*pts.first()?, *pts.last()?);
+    let m = pts[pts.len() / 2];
+    // Near-straight: every vertex within the fit tolerance of the end chord.
+    let ab = sub(b, a);
+    let l = norm(ab);
