+        return None;
+    }
+    let (c, ccw) = circumcircle(a, m, b)?;
+    let r = dist(a, c);
+    let (sweep, sag) = judge(pts, c, r, ccw, bound, false)?;
+    (sweep < TAU - 1e-9).then_some(Fit { c, r, ccw, sweep, sag })
